import { createRoot } from "react-dom/client"

export const restaurant = { name: "Mama Put Kitchen", area: "Yaba" }

function Header() {
  return (
    <header>
      <h1>{restaurant.name}</h1>
      <p>{restaurant.area}, Lagos</p>
    </header>
  )
}

function Footer() {
  return <footer>© {new Date().getFullYear()} {restaurant.name}</footer>
}

function Layout({ children }) {
  return (
    <>
      <Header />
      <main>{children}</main>
      <Footer />
    </>
  )
}

export default function App() {
  return (
    <Layout>
      <h2>Today's menu</h2>
    </Layout>
  )
}

createRoot(document.getElementById("root")).render(<App />)
